const orders = $('Get Orders Report').all().map(i => i.json).filter(o => o['Order ID']);
const meds = $('Get Medicines Report').all().map(i => i.json).filter(m => m['Medicine Name']);
const today = $now.setZone('Asia/Kolkata').toFormat('dd-MM-yyyy');
const LOW = 10;

const todays = orders.filter(o => String(o['Order Date'] || '').startsWith(today));
const isCancel = o => String(o['Order Status'] || '').trim().toLowerCase() === 'cancelled';
const ok = todays.filter(o => !isCancel(o));
const cancelled = todays.filter(isCancel);
const total = ok.reduce((s, o) => s + Number(o['Total Price'] || 0), 0);

const sold = {};
for (const o of ok) {
  const n = String(o['Medicine Name'] || '').split(',').map(s => s.trim());
  const q = String(o['Quantity'] || '').split(',').map(s => Number(s.trim()));
  n.forEach((x, i) => { if (x) sold[x] = (sold[x] || 0) + (q[i] || 0); });
}
const top = Object.entries(sold).sort((a, b) => b[1] - a[1]).slice(0, 5);
const low = meds.filter(m => Number(m['Quantity']) <= LOW);

const td = 'style="padding:8px;border-bottom:1px solid #eee;"';
const orderRows = ok.length
  ? ok.map(o => `<tr><td ${td}>#${o['Order ID']}</td><td ${td}>${o['Customer Name']}</td><td ${td}>${o['Medicine Name']}</td><td ${td}>₹${o['Total Price']}</td></tr>`).join('')
  : `<tr><td ${td} colspan="4">Aaj koi order nahi aaya.</td></tr>`;
const topRows = top.length
  ? top.map(t => `<tr><td ${td}>${t[0]}</td><td ${td}>${t[1]}</td></tr>`).join('')
  : `<tr><td ${td} colspan="2">-</td></tr>`;
const lowRows = low.length
  ? low.map(m => `<tr><td ${td}>${m['Medicine Name']}</td><td ${td}>${m['Quantity']}</td></tr>`).join('')
  : `<tr><td ${td} colspan="2">Sab stock theek hai.</td></tr>`;

const html = `
<div style="font-family:Arial,sans-serif;max-width:600px;margin:auto;">
 <tr>
    <td style="background:#0f766e;padding:24px 28px;">
      <table width="100%" cellpadding="0" cellspacing="0" border="0">
        <tr>
          <td align="left" style="width:100px;vertical-align:middle;padding-right:18px;">
            <img src="https://lh3.googleusercontent.com/d/1Ng2gDalChx-yp34ZF_TYVMFZpam98GEM" alt="Life Cure Pharmacy Logo" style="width:100px;height:100px;display:block;background:#ffffff;border-radius:20%;border:none;">
          </td>
          <td align="left" style="vertical-align:middle;">
            <div style="color:#ffffff;font-size:24px;font-weight:bold;line-height:1.2;">💊 Life Cure Pharmacy</div>
            <div style="color:#fecaca;font-size:14px;margin-top:6px;"></div>
          </td>
        </tr>
      </table>
    </td>
  </tr>
<p style="color:#555;">📅 ${today}</p>
<table style="width:100%;margin-bottom:16px;"><tr>
<td style="background:#f3f8f6;padding:12px;text-align:center;"><b>${ok.length}</b><br>Orders</td>
<td style="background:#f3f8f6;padding:12px;text-align:center;"><b>₹${total}</b><br>Total Sale</td>
<td style="background:#f3f8f6;padding:12px;text-align:center;"><b>${cancelled.length}</b><br>Cancelled</td>
</tr></table>
<h3>📦 Aaj ke Orders</h3>
<table style="width:100%;border-collapse:collapse;"><tr style="background:#eee;"><th align="left" style="padding:8px;">ID</th><th align="left" style="padding:8px;">Customer</th><th align="left" style="padding:8px;">Medicine</th><th align="left" style="padding:8px;">Total</th></tr>${orderRows}</table>
<h3>🏆 Sabse zyada bikne wali</h3>
<table style="width:100%;border-collapse:collapse;"><tr style="background:#eee;"><th align="left" style="padding:8px;">Medicine</th><th align="left" style="padding:8px;">Qty</th></tr>${topRows}</table>
<h3>⚠️ Kam / Khatam Stock</h3>
<table style="width:100%;border-collapse:collapse;"><tr style="background:#eee;"><th align="left" style="padding:8px;">Medicine</th><th align="left" style="padding:8px;">Stock</th></tr>${lowRows}</table>
</div>`;

return [{ json: { subject: `📊 Daily Sales Report — ${today} | ₹${total}`, html } }];
